import "./ProblemTable.css";

export interface ProblemRow {
  title: string;
  pattern: string;
  minutes: number;
  review: string;
  due: boolean;
}

export interface ProblemTableProps {
  rows: ProblemRow[];
}

export function ProblemTable({ rows }: ProblemTableProps) {
  return (
    <div
      className="problem-table-scroll"
      role="region"
      aria-label="Solved problems"
      tabIndex={0}
    >
      <table className="problem-table">
        <caption className="sr-only">Solved problems and their next review</caption>
        <thead>
          <tr>
            <th scope="col">Title</th>
            <th scope="col">Pattern</th>
            <th scope="col" className="num">Minutes</th>
            <th scope="col">Next review</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <tr key={`${row.title}-${index}`}>
              <th scope="row">{row.title}</th>
              <td className="pattern">{row.pattern}</td>
              <td className="num">{row.minutes}</td>
              <td className={row.due ? "review-cell review-cell--due" : "review-cell"}>
                {row.review}
                {row.due && <span className="due-badge">Due today</span>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
```

