.problem-table-scroll {
  overflow-x: auto;
}

.problem-table {
  width: 100%;
  border-collapse: collapse;
  font: inherit;
  color: var(--ink);
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1rem);
}

.problem-table th,
.problem-table td {
  padding: 0.6em 0.75em;
  border-bottom: 1px solid var(--hair);
  text-align: left;
  vertical-align: middle;
}

.problem-table thead th {
  color: var(--muted);
  font-weight: 600;
  border-bottom-color: var(--muted);
}

.problem-table tbody th {
  font-weight: 400;
}

.problem-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.problem-table .pattern {
  color: var(--muted);
}

.review-cell {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.review-cell--due {
  background: var(--cresyl-wash);
  box-shadow: inset 3px 0 0 var(--cresyl);
}

.due-badge {
  display: inline-block;
  margin-left: 0.5em;
  padding: 0.1em 0.6em;
  border: 1px solid var(--cresyl);
  border-radius: 999px;
  color: var(--ink);
  font-size: 0.8em;
  white-space: nowrap;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
